function gate(idx) {
  const exits = [
    ["shutdown()", "const shutdown = async (signal: string)", "process.exit(0)"],
    ["uncaughtException", 'process.on("uncaughtException"', "process.exit(1)"],
    ["unhandledRejection", 'process.on("unhandledRejection"', "process.exit(1)"],
    ["main().catch", "main().catch(", "process.exit(1)"],
  ];
  const fails = [];
  const anchorAt = exits.map(([name, anchor]) => {
    const i = idx.indexOf(anchor);
    if (i < 0) fails.push(`anchor missing: ${name}`);
    return i;
  });
  exits.forEach(([name, , exitCall], n) => {
    const block = idx.slice(anchorAt[n], n + 1 < anchorAt.length ? anchorAt[n + 1] : idx.length);
    const drainAt = block.indexOf("closeAllStatusChannels(");
