// 臨時覆核 fuzz：比對 4d5f969 新版 hide/cut 與 parent 舊版行為。
import { hideTrailingUnterminatedToken, cutPendingTokenTail, transform } from "G:/AI/telegram-kiro-bridge-main/src/observerTransformer.js";

const TOKEN_OPENER_NAMES = [
  "GOAL_DONE","SKILL_USED","SKILL_PROPOSE","ASK","SCHEDULE",
  "SEND_FILE","STICKER","WIKI_QUERY","SPECIALIST_PROXY","MOA_PLAN","SELF_EVAL",
];
const RE_SRC = `<<(?:${TOKEN_OPENER_NAMES.join("|")}):|<<(?:RESTART|CONTINUE)(?::|>?$)`;
const OPENERS = [...TOKEN_OPENER_NAMES.map(n=>`<<${n}:`), "<<RESTART>>","<<RESTART:","<<CONTINUE>>"];

function hideOld(text) {
  const re = new RegExp(RE_SRC, "g");
  let last = -1;
  for (;;) { const m = re.exec(text); if (!m) break; last = m.index; }
  if (last < 0) return text;
  const tail = text.slice(last);
  if (tail.includes(">>")) return text;
  return text.slice(0, last).replace(/\s+$/, "") + "\n…";
}
function cutOld(text) {
  const idx = text.lastIndexOf("<<");
  if (idx >= 0 && !text.includes(">>", idx)) {
    const tail = text.slice(idx);
    if (OPENERS.some(o => o.startsWith(tail) || tail.startsWith(o))) {
      return text.slice(0, idx).replace(/\s+$/, "");
    }
  }
  if (text.endsWith("<")) return text.slice(0, -1).replace(/\s+$/, "");
  return text;
}

const frags = [
  "<<", ">>", ">", "<", ":", "|", " ", "\n", "a", "。",
  "SELF_EVAL", "SEL", "ASK", "CONTINUE", "CONT", "RESTART", "STICKER",
  "<<SELF_EVAL:88|", "<<ASK:id|q|y|n", "<<CONTINUE:", "<<CONTINUE",
  "<<RESTART:", "<<RESTART>", "<<RESTART>>", "價格 << 100", "a<<b",
  "<<STICKER:ok>>", "<<GOAL_DONE:done>>", "<<SEL", "<<WIKI_QUERY:x",
];
function rnd(n) { return Math.floor(Math.random() * n); }
function gen() {
  let s = "";
  const k = 1 + rnd(8);
  for (let i = 0; i < k; i++) s += frags[rnd(frags.length)];
  return s;
}

let hideDiff = 0, invariantViol = 0, cutShrunkCoverage = 0, newOnlyAppendViol = 0;
const samples = { hide: [], inv: [], cov: [], app: [] };

function frames(render, full) {
  const out = [];
  for (let i = 1; i <= full.length; i++) {
    const f = render(full.slice(0, i));
    if (!out.length || out[out.length-1] !== f) out.push(f);
  }
  return out;
}
function appendViol(fs) {
  for (let i = 1; i < fs.length; i++) if (!fs[i].startsWith(fs[i-1])) return true;
  return false;
}

const N = 20000;
for (let t = 0; t < N; t++) {
  const x = gen();
  // A) hide 等價
  const ho = hideOld(x), hn = hideTrailingUnterminatedToken(x);
  if (ho !== hn) { hideDiff++; if (samples.hide.length < 5) samples.hide.push({x, ho, hn}); }
  // B) 不變式：hide 會藏 ⇒ cut 必須在同一錨點（或更前）扣住
  if (hn !== x) {
    const cn = cutPendingTokenTail(x);
    if (!(cn.length < x.length && hn.startsWith(cn.slice(0, Math.min(cn.length, hn.length))) || cn.length <= hn.length - 2)) {
      // 寬鬆檢查失敗再細看：cut 結果必須是 hide 結果去掉 "\n…" 的前綴
      const hideHead = hn.slice(0, -2); // 去掉 "\n…"
      if (!(hideHead.startsWith(cn) || cn === hideHead)) {
        invariantViol++; if (samples.inv.length < 5) samples.inv.push({x, hn, cn});
      }
    }
  }
  // C) 舊 cut 有扣、新 cut 沒扣（覆蓋縮減）
  const co = cutOld(x), cn2 = cutPendingTokenTail(x);
  if (co !== x && cn2 === x) { cutShrunkCoverage++; if (samples.cov.length < 5) samples.cov.push({x, co}); }
}

// D) append-only：新管線違反但舊管線(parent cut)不違反 → 新回歸
const NEWP = (b) => transform(cutPendingTokenTail(b), null).text;
const OLDP = (b) => transform(cutOld(b), null).text;
for (let t = 0; t < 800; t++) {
  const x = gen();
  const nv = appendViol(frames(NEWP, x));
  if (nv) {
    const ov = appendViol(frames(OLDP, x));
    if (!ov) { newOnlyAppendViol++; if (samples.app.length < 5) samples.app.push({x}); }
  }
}

console.log(JSON.stringify({ N, hideDiff, invariantViol, cutShrunkCoverage, newOnlyAppendViol, samples }, null, 2));
