import('./dist/telegram-ui.js').then(async (ui) => {
  const parsers = { parseDuration:()=>null, parseAbsoluteTime:()=>null, parseRecurrence:()=>null, computeNextRunAt:()=>null };
  const mk = (buffer) => ({ chatId:1, buffer, tools:[], thinking:false });
  // 重現 3d-long 語料，分類 crossedCut 的來源：真正超額釋放 vs 尾端已終止 token 的錨點失效
  let seed = 20260802;
  const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
  const CHUNKS = [
    '散'.repeat(300), '文'.repeat(1500), '\n\n\n\n', '\n',
    '<<SELF_EVAL:', '<<ASK:q|x', '<<SPECIALIST_PROXY:a|', '<<STICKER:happy>>', '。',
  ];
  let visTotal = 0, visViaTerminated = 0, visViaOverCap = 0;
