const fs=require('fs');
const crypto=require('crypto');
const rl=require('readline').createInterface({input:fs.createReadStream('logs/draft-frames.jsonl')});
const since=Date.parse('2026-08-01T12:25:00Z');
const byDraft={};
rl.on('line',l=>{ let r; try{r=JSON.parse(l)}catch(e){return}
  if(Date.parse(r.at)<since) return;
  const h=crypto.createHash('sha1').update(r.content).digest('hex').slice(0,8);
  (byDraft[r.draftId]=byDraft[r.draftId]||[]).push({at:r.at,ms:r.ms,len:r.len,reason:r.reason,h});
});
rl.on('close',()=>{
  let totalDup=0; const gaps=[];
  for(const [id,fr] of Object.entries(byDraft)){
    let dup=0;
    for(let i=1;i<fr.length;i++){
      if(fr[i].h===fr[i-1].h){ dup++; totalDup++; gaps.push({at:fr[i].at.slice(11,19),id:id.slice(-6),len:fr[i].len,reason:fr[i].reason,dtS:((fr[i].ms-fr[i-1].ms)/1000).toFixed(1)}); }
    }
    console.log('draft',id,'frames='+fr.length,'identical-resend='+dup);
  }
  console.log('TOTAL identical re-sends:', totalDup);
  console.log('--- each (no content shown) ---');
  for(const g of gaps) console.log(g.at,'d'+g.id,'len='+g.len,'reason='+g.reason,'sincePrevFrame='+g.dtS+'s');
});
